INSERT INTO events (issuer_id,event_date,kind,headline,detail,source,is_key) VALUES ((SELECT id FROM issuers WHERE ticker='TOVX'),'2018-08-10','split','One-for-thirty-five reverse stock split',NULL,'Prospectus 2025-05-07',0);
INSERT INTO events (issuer_id,event_date,kind,headline,detail,source,is_key) VALUES ((SELECT id FROM issuers WHERE ticker='TOVX'),'2022-03-10','acquisition','Acquisition of VCN Biosciences, S.L. completed','Contingent consideration of up to $70.2 million payable on milestones.','Form 10-Q',1);
INSERT INTO events (issuer_id,event_date,kind,headline,detail,source,is_key) VALUES ((SELECT id FROM issuers WHERE ticker='TOVX'),'2022-07-25','split','One-for-ten reverse stock split',NULL,'Certificate of Change',0);
INSERT INTO events (issuer_id,event_date,kind,headline,detail,source,is_key) VALUES ((SELECT id FROM issuers WHERE ticker='TOVX'),'2022-07-28','offering','Series C and Series D Convertible Preferred sold to MSD Credit Opportunity Master Fund, L.P.','375,000 preferred shares at $8.00, approximately $3.0 million gross. Series D carried 20,000 votes per share. A.G.P. financial advisor, $175,000 fee.','Form 8-K 2022-07-29',1);
INSERT INTO events (issuer_id,event_date,kind,headline,detail,source,is_key) VALUES ((SELECT id FROM issuers WHERE ticker='TOVX'),'2022-09-30','vote','Authorized common stock increased from 20,000,000 to 350,000,000','The proxy states, under "Impact of Preferred Stock on Certain Proposals," that the preferred stock was issued in order to assist with procuring the vote necessary to effect the increase and the name change.','DEF 14A 2022-08-16',1);
INSERT INTO events (issuer_id,event_date,kind,headline,detail,source,is_key) VALUES ((SELECT id FROM issuers WHERE ticker='TOVX'),'2022-10-12','name_change','Name changed to Theriva Biologics, Inc.; ticker changed to TOVX',NULL,'Form 8-K',0);
INSERT INTO events (issuer_id,event_date,kind,headline,detail,source,is_key) VALUES ((SELECT id FROM issuers WHERE ticker='TOVX'),'2024-05-02','agreement','At-the-market sales agreement amended; A.G.P. as sales agent','B. Riley Securities ceased to be a party 2024-05-01.','Form 10-Q',0);
INSERT INTO events (issuer_id,event_date,kind,headline,detail,source,is_key) VALUES ((SELECT id FROM issuers WHERE ticker='TOVX'),'2024-08-26','split','One-for-twenty-five reverse stock split','Board-approved 2024-08-15 without a stockholder vote. Outstanding reduced from 25,131,230 to 1,005,249. Authorized reduced from 350,000,000 to 14,000,000, then restored to 350,000,000.','Form 10-Q Q1 2025',1);
INSERT INTO events (issuer_id,event_date,kind,headline,detail,source,is_key) VALUES ((SELECT id FROM issuers WHERE ticker='TOVX'),'2024-09-27','offering','Public offering closed','918,600 shares, 510,000 pre-funded warrants, 1,428,600 common warrants at $2.00. Gross proceeds approximately $2.5 million.','Form 10-Q',1);
INSERT INTO events (issuer_id,event_date,kind,headline,detail,source,is_key) VALUES ((SELECT id FROM issuers WHERE ticker='TOVX'),'2025-05-07','offering','VIRAGE Phase 2b results announced; offering priced the same day','$1.10 per share with a five-year warrant at $1.10. Total $7,495,170.72. A.G.P. sole placement agent, fee $524,661.95. Prior close $1.36; closed $0.81 that day.','424B5 2025-05-08',1);
INSERT INTO events (issuer_id,event_date,kind,headline,detail,source,is_key) VALUES ((SELECT id FROM issuers WHERE ticker='TOVX'),'2025-09-30','workforce','Workforce reduction of seven employees, 32 percent of the global workforce',NULL,'Form 10-Q',0);
INSERT INTO events (issuer_id,event_date,kind,headline,detail,source,is_key) VALUES ((SELECT id FROM issuers WHERE ticker='TOVX'),'2025-10-16','inducement','Inducement Agreement entered; warrants for 8,092,280 shares repriced from $2.00 to $0.54',NULL,'Form 8-K; 424B5',1);
INSERT INTO events (issuer_id,event_date,kind,headline,detail,source,is_key) VALUES ((SELECT id FROM issuers WHERE ticker='TOVX'),'2025-10-17','inducement','Warrants exercised for cash at $0.54; 16,184,560 new warrants issued','Gross proceeds approximately $4.4 million before agent fees of $356,000 and expenses of $72,000. Value transferred measured at $5.9 million; $1.5 million excess recorded as a deemed dividend. The stock closed at $0.42 that day.','Form 10-Q Q2 2026',1);
INSERT INTO events (issuer_id,event_date,kind,headline,detail,source,is_key) VALUES ((SELECT id FROM issuers WHERE ticker='TOVX'),'2025-12-15','vote','Special meeting called; no quorum present','Meetings called for 2026-02-11 and 2026-04-09 also failed for lack of quorum.','DEF 14A 2026-04-30',1);
INSERT INTO events (issuer_id,event_date,kind,headline,detail,source,is_key) VALUES ((SELECT id FROM issuers WHERE ticker='TOVX'),'2026-02-18','license','SYN-020 out-licensed to Rasayana Therapeutics, Inc.','Upfront payment $300,000; development milestones up to $16,000,000 and sales milestones up to $22,000,000.','Form 10-Q',0);
INSERT INTO events (issuer_id,event_date,kind,headline,detail,source,is_key) VALUES ((SELECT id FROM issuers WHERE ticker='TOVX'),'2026-07-24','employment','Board approved accelerated option vesting upon execution of a definitive merger agreement','Applies to all option agreements for directors and U.S. employees, and to unvested options held by Spanish employees.','Form 10-Q Q2 2026',1);
INSERT INTO events (issuer_id,event_date,kind,headline,detail,source,is_key) VALUES ((SELECT id FROM issuers WHERE ticker='TOVX'),'2026-08-03','vote','Stockholders approved the exercise of 16,184,560 warrants at $0.54','Fourth meeting called for this purpose. Warrants expire 2031-08-03. 2020 Stock Plan increased to 6,500,000 shares.','Form 10-Q Q2 2026',1);
INSERT INTO events (issuer_id,event_date,kind,headline,detail,source,is_key) VALUES ((SELECT id FROM issuers WHERE ticker='TOVX'),'2026-08-10','employment','Amended and restated employment agreement with the Chief Executive Officer','Annual base salary $687,562. Change-of-control severance of two times base salary plus target bonus, of which $500,000 allocated to a covenant not to compete. Change in Control includes a reverse merger with a non-listed private operating company.','Form 10-Q Q2 2026',1);
INSERT INTO events (issuer_id,event_date,kind,headline,detail,source,is_key) VALUES ((SELECT id FROM issuers WHERE ticker='TOVX'),'2026-08-11','filing','Form 10-Q for the quarter ended 2026-06-30 filed','Cash $9.6 million as of early August 2026. Going concern paragraph. Company states it is evaluating strategic alternatives including an acquisition, merger, reverse merger, other business combination, or sale of assets.','Form 10-Q Q2 2026',1);

